import {createHash} from "node:crypto";
import {proveDirectFactLookup,directFactLookupSourceId,directFactProofCompatible} from "./src/domain/memory-direct-recall.ts";
const lineage={sourceId:"s",sourceEventId:"e",sourceRevision:1,role:"user",trust:"user_assertion"};
const base={_id:"",tenantId:"t",memorySpaceId:"m",ownerPrincipalId:"p",lineage,extractionPolicyVersion:"v1",factType:"preference",confidence:91,sourceType:"manual",tags:[],version:1,createdAt:1000,updatedAt:1000};
const makeSource=content=>({tenantId:"t",memorySpaceId:"m",ownerPrincipalId:"p",lineage,content,contentHash:createHash("sha256").update(content).digest("hex"),createdAt:1000});
const query="What is my favorite fruit?";
const cases=[
 {name:"unstructured same-source contradiction",facts:[{...base,factId:"f1",fact:"My favorite fruit is apricot."},{...base,factId:"f2",fact:"My favorite fruit is pear."}],source:makeSource("My favorite fruit is apricot.")},
 {name:"unstructured canonical source value mismatch",facts:[{...base,factId:"f1",fact:"My favorite fruit is apricot."},{...base,factId:"f2",fact:"My favorite fruit is apricot."}],source:makeSource("My favorite fruit is pear.")}
];
const results=cases.map(row=>{const candidates={facts:row.facts,candidateWorkBound:false},proof=proveDirectFactLookup(query,candidates,1000,1,row.source);return {name:row.name,source:row.source.content,facts:row.facts.map(f=>f.fact),expectedProof:false,actualProof:proof!==undefined,prospectiveSourceId:directFactLookupSourceId(query,candidates,1000,1),actualCompatible:proof?directFactProofCompatible(proof,row.facts,1000):false};});
console.log(JSON.stringify(results,null,2));
if(results.some(row=>row.actualProof!==row.expectedProof))process.exitCode=1;
